-- Oracle SH: source tables → events (refdata ingest). Money in cents. Dates are midnight UTC.
-- currency is generated by its rule in views.sql and not read.

-- entity: countries
SELECT CAST(country_id AS TEXT) AS ext_id, country_iso_code, country_name, country_subregion, country_subregion_id, country_region, country_region_id, country_total, country_total_id
FROM countries ORDER BY country_id;

-- entity: channels
SELECT CAST(channel_id AS TEXT) AS ext_id, channel_desc, channel_class, channel_class_id, channel_total, channel_total_id
FROM channels ORDER BY channel_id;

-- entity: promotions
SELECT CAST(promo_id AS TEXT) AS ext_id, promo_name, promo_subcategory, promo_subcategory_id, promo_category, promo_category_id, promo_cost, promo_begin_date, promo_end_date, promo_total, promo_total_id
FROM promotions ORDER BY promo_id;

-- entity: customers
SELECT CAST(cust_id AS TEXT) AS ext_id, cust_eff_from || ' 00:00:00' AS created_at, cust_first_name, cust_last_name, cust_gender, cust_year_of_birth, cust_marital_status, cust_street_address, cust_postal_code, cust_city, cust_city_id, cust_state_province, cust_state_province_id, CAST(country_id AS TEXT) AS country_id, cust_main_phone_number, cust_income_level, cust_credit_limit, cust_email, cust_total, cust_total_id, cust_src_id, cust_eff_from, cust_eff_to, cust_valid
FROM customers ORDER BY cust_id;

-- entity: times
SELECT CAST(time_id AS TEXT) AS ext_id, day_name, day_number_in_week, day_number_in_month, calendar_week_number, fiscal_week_number, week_ending_day, week_ending_day_id, calendar_month_number, fiscal_month_number, calendar_month_desc, calendar_month_id, fiscal_month_desc, fiscal_month_id, days_in_cal_month, days_in_fis_month, end_of_cal_month, end_of_fis_month, calendar_month_name, fiscal_month_name, calendar_quarter_desc, calendar_quarter_id, fiscal_quarter_desc, fiscal_quarter_id, days_in_cal_quarter, days_in_fis_quarter, end_of_cal_quarter, end_of_fis_quarter, calendar_quarter_number, fiscal_quarter_number, calendar_year, calendar_year_id, fiscal_year, fiscal_year_id, days_in_cal_year, days_in_fis_year, end_of_cal_year, end_of_fis_year
FROM times ORDER BY time_id;

-- entity: products
-- Catalogued rows, then a placeholder for every sold or quoted id with no row.
SELECT CAST(prod_id AS TEXT) AS ext_id, 1 AS catalogued, prod_name, prod_desc, prod_subcategory,
       prod_subcategory_desc, prod_category, prod_category_desc, prod_unit_of_measure,
       prod_pack_size, prod_status, prod_total, prod_src_id, prod_eff_from, prod_eff_to,
       prod_valid, prod_subcategory_id, prod_category_id, prod_weight_class, supplier_id,
       prod_total_id, prod_list_price, prod_min_price
FROM products
UNION ALL
SELECT CAST(prod_id AS TEXT), 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
       NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL
FROM (SELECT prod_id FROM sales UNION SELECT prod_id FROM costs)
WHERE prod_id NOT IN (SELECT prod_id FROM products)
ORDER BY 1;

-- entity: demographics
SELECT CAST(cust_id AS TEXT) AS ext_id, CAST(cust_id AS TEXT) AS customer_id, education,
       occupation, household_size, yrs_residence, affinity_card, cricket, baseball, tennis,
       soccer, golf, unknown, misc, comments
FROM supplementary_demographics ORDER BY cust_id;

-- event: price_quoted owner=prod_id
-- Before the day's sales: its block comes first.
SELECT time_id || ' 00:00:00' AS event_time, CAST(prod_id AS TEXT) AS prod_id,
       CAST(channel_id AS TEXT) AS channel_id, CAST(promo_id AS TEXT) AS promo_id,
       CAST(round(unit_cost * 100) AS INTEGER) AS unit_cost,
       CAST(round(unit_price * 100) AS INTEGER) AS unit_price
FROM costs ORDER BY rowid;

-- event: unit_sold owner=cust_id
SELECT time_id || ' 00:00:00' AS event_time, CAST(cust_id AS TEXT) AS cust_id,
       CAST(prod_id AS TEXT) AS prod_id, CAST(channel_id AS TEXT) AS channel_id,
       CAST(promo_id AS TEXT) AS promo_id, quantity_sold,
       CAST(round(amount_sold * 100) AS INTEGER) AS amount_sold
FROM sales ORDER BY rowid;
